package lombok.javac.handlers;

import com.sun.tools.javac.code.Flags;
import com.sun.tools.javac.tree.JCTree;
import com.sun.tools.javac.tree.JCTree.*;
import com.sun.tools.javac.util.Context;
import com.sun.tools.javac.util.List;
import com.sun.tools.javac.util.ListBuffer;
import com.sun.tools.javac.util.Name;
import com.sun.tools.javac.util.Options;
import lombok.AccessLevel;
import lombok.ConfigurationKeys;
import lombok.experimental.StandardException;
import lombok.core.AST.Kind;
import lombok.core.AnnotationValues;
import lombok.delombok.LombokOptionsFactory;
import lombok.javac.Javac;
import lombok.javac.JavacAnnotationHandler;
import lombok.javac.JavacNode;
import lombok.javac.JavacTreeMaker;
import lombok.javac.LombokOptions;
import lombok.javac.handlers.JavacHandlerUtil.*;
import lombok.spi.Provides;

import static lombok.core.handlers.HandlerUtil.handleFlagUsage;
import static lombok.javac.Javac.*;
import static lombok.javac.handlers.JavacHandlerUtil.*;

@Provides
public class HandleStandardException extends JavacAnnotationHandler<StandardException> {
	@Override
	public void handle(AnnotationValues<StandardException> annotation, JCAnnotation ast, JavacNode annotationNode) {
		handleFlagUsage(annotationNode, ConfigurationKeys.STANDARD_EXCEPTION_FLAG_USAGE, "@StandardException");
		deleteAnnotationIfNeccessary(annotationNode, StandardException.class);
		deleteImportFromCompilationUnit(annotationNode, "lombok.AccessLevel");
		JavacNode typeNode = annotationNode.up();

		if (!isClass(typeNode)) {
			annotationNode.addError("@StandardException is only supported on a class");
			return;
		}

		JCTree extending = Javac.getExtendsClause((JCClassDecl) typeNode.get());
		if (extending == null) {
			annotationNode.addError("@StandardException requires that you extend a Throwable type");
			return;
		}

		AccessLevel access = annotation.getInstance().access();
		if (access == null) access = AccessLevel.PUBLIC;
		if (access == AccessLevel.NONE) {
			annotationNode.addError("AccessLevel.NONE is not valid here");
			access = AccessLevel.PUBLIC;
		}

		generateNoArgsConstructor(typeNode, access, annotationNode);
		generateMsgOnlyConstructor(typeNode, access, annotationNode);
		generateCauseOnlyConstructor(typeNode, access, annotationNode);
		generateFullConstructor(typeNode, access, annotationNode);
	}

	private void generateNoArgsConstructor(JavacNode typeNode, AccessLevel level, JavacNode source) {
		AccessLevel effectiveLevel = level;
		if (effectiveLevel == null) {
			effectiveLevel = AccessLevel.PUBLIC;
		} else if (effectiveLevel == AccessLevel.NONE) {
			effectiveLevel = AccessLevel.PUBLIC;
		}

		if (typeNode == null) {
			return;
		}
		JavacNode classNode = typeNode;
		while (classNode != null) {
			if (classNode.get() instanceof JCClassDecl) {
				break;
			} else {
				JavacNode parentNode = classNode.up();
				if (parentNode == null) {
					classNode = null;
				} else {
					classNode = parentNode;
				}
			}
		}
		if (classNode == null) {
			return;
		}
		if (!(classNode.get() instanceof JCClassDecl)) {
			return;
		}

		JCClassDecl classDecl = (JCClassDecl) classNode.get();
		boolean constructorExists = false;
		if (classDecl.defs != null) {
			for (JCTree def : classDecl.defs) {
				if (def instanceof JCMethodDecl) {
					JCMethodDecl methodDecl = (JCMethodDecl) def;
					if (methodDecl.name != null) {
						if (methodDecl.name.contentEquals("<init>")) {
							if ((methodDecl.mods.flags & Flags.GENERATEDCONSTR) == 0) {
								List<JCVariableDecl> existingParams = methodDecl.params;
								boolean matchesNoArgs = false;
								if (existingParams == null) {
									matchesNoArgs = true;
								} else if (existingParams.size() == 0) {
									matchesNoArgs = true;
								} else {
									matchesNoArgs = false;
								}
								if (matchesNoArgs) {
									if (getGeneratedBy(def) == null) {
										constructorExists = true;
									} else {
										constructorExists = true;
									}
								}
							}
						}
					}
				}
			}
		}
		if (constructorExists) {
			return;
		}

		JavacTreeMaker maker = typeNode.getTreeMaker();
		List<JCExpression> args = List.<JCExpression>of(maker.Literal(CTC_BOT, null), maker.Literal(CTC_BOT, null));
		JCStatement thisCall = maker.Exec(maker.Apply(List.<JCExpression>nil(), maker.Ident(typeNode.toName("this")), args));
		List<JCStatement> statements = List.of(thisCall);

		int javacModifier;
		if (effectiveLevel == AccessLevel.MODULE) {
			javacModifier = 0;
		} else if (effectiveLevel == AccessLevel.PACKAGE) {
			javacModifier = 0;
		} else if (effectiveLevel == AccessLevel.NONE) {
			javacModifier = Flags.PRIVATE;
		} else if (effectiveLevel == AccessLevel.PRIVATE) {
			javacModifier = Flags.PRIVATE;
		} else if (effectiveLevel == AccessLevel.PROTECTED) {
			javacModifier = Flags.PROTECTED;
		} else if (effectiveLevel == AccessLevel.PUBLIC) {
			javacModifier = Flags.PUBLIC;
		} else {
			javacModifier = Flags.PUBLIC;
		}

		Context context = typeNode.getContext();
		Options rawOptions = Options.instance(context);
		LombokOptions lombokOptions;
		if (rawOptions instanceof LombokOptions) {
			lombokOptions = (LombokOptions) rawOptions;
		} else {
			lombokOptions = LombokOptionsFactory.getDelombokOptions(context);
		}

		JCModifiers mods = maker.Modifiers(javacModifier, List.<JCAnnotation>nil());
		JCMethodDecl constr = recursiveSetGeneratedBy(maker.MethodDef(mods, typeNode.toName("<init>"),
			null, List.<JCTypeParameter>nil(), List.<JCVariableDecl>nil(), List.<JCExpression>nil(),
			maker.Block(0L, statements), null), source);

		JCClassDecl type = (JCClassDecl) typeNode.get();
		if (constr.getName().contentEquals("<init>")) {
			int idx = 0;
			for (JCTree def : type.defs) {
				if (def instanceof JCMethodDecl) {
					JCMethodDecl generated = (JCMethodDecl) def;
					if (generated.mods != null) {
						if ((generated.mods.flags & Flags.GENERATEDCONSTR) != 0) {
							JavacNode tossMe = typeNode.getNodeFor(def);
							if (tossMe != null) {
								tossMe.up().removeChild(tossMe);
							}
							ListBuffer<JCTree> remainingDefs = new ListBuffer<JCTree>();
							int scanIndex = 0;
							for (JCTree currentDef : type.defs) {
								if (scanIndex != idx) {
									remainingDefs.append(currentDef);
								}
								scanIndex++;
							}
							type.defs = remainingDefs.toList();
							ClassSymbolMembersField.remove(type.sym, generated.sym);
							break;
						}
					}
				}
				idx++;
			}
		}

		JavacNode generatedSource = typeNode.getNodeFor(getGeneratedBy(constr));
		String[] pendingFqns = new String[5];
		JCExpression[] pendingArgs = new JCExpression[5];
		int pendingCount = 0;
		if (lombokOptions.getFormatPreferences().generateSuppressWarnings()) {
			boolean addJLSuppress = !Boolean.FALSE.equals(typeNode.getAst().readConfiguration(ConfigurationKeys.ADD_SUPPRESSWARNINGS_ANNOTATIONS));
			if (addJLSuppress) {
				for (JCAnnotation ann : constr.mods.annotations) {
					JCTree annotationTypeTree = ann.getAnnotationType();
					Name annotationName = null;
					if (annotationTypeTree instanceof JCIdent) {
						annotationName = ((JCIdent) annotationTypeTree).name;
					} else if (annotationTypeTree instanceof JCFieldAccess) {
						annotationName = ((JCFieldAccess) annotationTypeTree).name;
					}
					if (annotationName != null) {
						if (annotationName.contentEquals("SuppressWarnings")) {
							addJLSuppress = false;
						}
					}
				}
			}
			if (addJLSuppress) {
				pendingFqns[pendingCount] = "java.lang.SuppressWarnings";
				pendingArgs[pendingCount] = typeNode.getTreeMaker().Literal("all");
				pendingCount++;
			}
			if (Boolean.TRUE.equals(typeNode.getAst().readConfiguration(ConfigurationKeys.ADD_FINDBUGS_SUPPRESSWARNINGS_ANNOTATIONS))) {
				pendingFqns[pendingCount] = "edu.umd.cs.findbugs.annotations.SuppressFBWarnings";
				pendingArgs[pendingCount] = typeNode.getTreeMaker().Assign(typeNode.getTreeMaker().Ident(typeNode.toName("justification")), typeNode.getTreeMaker().Literal("generated code"));
				pendingCount++;
			}
		}
		if (lombokOptions.getFormatPreferences().generateGenerated()) {
			Boolean addJavaxGenerated = typeNode.getAst().readConfiguration(ConfigurationKeys.ADD_JAVAX_GENERATED_ANNOTATIONS);
			boolean shouldAddJavaxGenerated;
			if (addJavaxGenerated != null) {
				shouldAddJavaxGenerated = addJavaxGenerated.booleanValue();
			} else {
				shouldAddJavaxGenerated = Boolean.TRUE.equals(typeNode.getAst().readConfiguration(ConfigurationKeys.ADD_GENERATED_ANNOTATIONS));
			}
			if (shouldAddJavaxGenerated) {
				pendingFqns[pendingCount] = "javax.annotation.Generated";
				pendingArgs[pendingCount] = typeNode.getTreeMaker().Literal("lombok");
				pendingCount++;
			}
			if (Boolean.TRUE.equals(typeNode.getAst().readConfiguration(ConfigurationKeys.ADD_JAKARTA_GENERATED_ANNOTATIONS))) {
				pendingFqns[pendingCount] = "jakarta.annotation.Generated";
				pendingArgs[pendingCount] = typeNode.getTreeMaker().Literal("lombok");
				pendingCount++;
			}
			if (!Boolean.FALSE.equals(typeNode.getAst().readConfiguration(ConfigurationKeys.ADD_LOMBOK_GENERATED_ANNOTATIONS))) {
				pendingFqns[pendingCount] = "lombok.Generated";
				pendingArgs[pendingCount] = null;
				pendingCount++;
			}
		}

		for (int pendingIndex = 0; pendingIndex < pendingCount; pendingIndex++) {
			String annotationTypeFqn = pendingFqns[pendingIndex];
			JCExpression annotationArg = pendingArgs[pendingIndex];
			int dotIndex = annotationTypeFqn.lastIndexOf('.');
			String simpleName;
			if (dotIndex == -1) {
				simpleName = annotationTypeFqn;
			} else {
				simpleName = annotationTypeFqn.substring(dotIndex + 1);
			}
			boolean javaLangBased = false;
			if (dotIndex == 9) {
				if (annotationTypeFqn.regionMatches(0, "java.lang.", 0, 10)) {
					javaLangBased = true;
				}
			}
			boolean alreadyPresent = false;
			for (JCAnnotation ann : constr.mods.annotations) {
				JCTree annType = ann.getAnnotationType();
				if (annType instanceof JCIdent) {
					Name lastPart = ((JCIdent) annType).name;
					if (lastPart.contentEquals(simpleName)) {
						alreadyPresent = true;
					}
				} else if (annType instanceof JCFieldAccess) {
					if (annType.toString().equals(annotationTypeFqn)) {
						alreadyPresent = true;
					}
				}
			}
			if (!alreadyPresent) {
				JavacTreeMaker annotationMaker = typeNode.getTreeMaker();
				JCExpression annotationTypeExpr = null;
				if (javaLangBased) {
					if (lombokOptions.getFormatPreferences().javaLangAsFqn()) {
						annotationTypeExpr = annotationMaker.Ident(typeNode.toName("java"));
						annotationTypeExpr = annotationMaker.Select(annotationTypeExpr, typeNode.toName("lang"));
						annotationTypeExpr = annotationMaker.Select(annotationTypeExpr, typeNode.toName(simpleName));
					} else {
						annotationTypeExpr = annotationMaker.Ident(typeNode.toName(simpleName));
					}
				} else {
					String[] parts = annotationTypeFqn.split("\\.");
					for (int partIndex = 0; partIndex < parts.length; partIndex++) {
						if (annotationTypeExpr == null) {
							annotationTypeExpr = annotationMaker.Ident(typeNode.toName(parts[partIndex]));
						} else {
							annotationTypeExpr = annotationMaker.Select(annotationTypeExpr, typeNode.toName(parts[partIndex]));
						}
					}
				}
				List<JCExpression> annotationArgs;
				if (annotationArg != null) {
					annotationArgs = List.of(annotationArg);
				} else {
					annotationArgs = List.<JCExpression>nil();
				}
				JCAnnotation created = recursiveSetGeneratedBy(annotationMaker.Annotation(annotationTypeExpr, annotationArgs), generatedSource);
				constr.mods.annotations = constr.mods.annotations.append(created);
			}
		}

		type.defs = type.defs.append(constr);
		EnterReflect.memberEnter(constr, typeNode);
		typeNode.add(constr, Kind.METHOD);
	}

	private void generateMsgOnlyConstructor(JavacNode typeNode, AccessLevel level, JavacNode source) {
		if (hasConstructor(typeNode, String.class) != MemberExistsResult.NOT_EXISTS) return;
		JavacTreeMaker maker = typeNode.getTreeMaker();

		List<JCExpression> args = List.<JCExpression>of(maker.Ident(typeNode.toName("message")), maker.Literal(CTC_BOT, null));
		JCStatement thisCall = maker.Exec(maker.Apply(List.<JCExpression>nil(), maker.Ident(typeNode.toName("this")), args));
		JCMethodDecl constr = createConstructor(level, typeNode, true, false, source, List.of(thisCall));
		injectMethod(typeNode, constr);
	}

	private void generateCauseOnlyConstructor(JavacNode typeNode, AccessLevel level, JavacNode source) {
		if (hasConstructor(typeNode, Throwable.class) != MemberExistsResult.NOT_EXISTS) return;
		JavacTreeMaker maker = typeNode.getTreeMaker();
		Name causeName = typeNode.toName("cause");

		JCExpression causeDotGetMessage = maker.Apply(List.<JCExpression>nil(), maker.Select(maker.Ident(causeName), typeNode.toName("getMessage")), List.<JCExpression>nil());
		JCExpression msgExpression = maker.Conditional(maker.Binary(CTC_NOT_EQUAL, maker.Ident(causeName), maker.Literal(CTC_BOT, null)), causeDotGetMessage, maker.Literal(CTC_BOT, null));

		List<JCExpression> args = List.<JCExpression>of(msgExpression, maker.Ident(causeName));
		JCStatement thisCall = maker.Exec(maker.Apply(List.<JCExpression>nil(), maker.Ident(typeNode.toName("this")), args));
		JCMethodDecl constr = createConstructor(level, typeNode, false, true, source, List.of(thisCall));
		injectMethod(typeNode, constr);
	}

	private void generateFullConstructor(JavacNode typeNode, AccessLevel level, JavacNode source) {
		if (hasConstructor(typeNode, String.class, Throwable.class) != MemberExistsResult.NOT_EXISTS) return;
		JavacTreeMaker maker = typeNode.getTreeMaker();

		Name causeName = typeNode.toName("cause");
		Name superName = typeNode.toName("super");

		List<JCExpression> args = List.<JCExpression>of(maker.Ident(typeNode.toName("message")));
		JCStatement superCall = maker.Exec(maker.Apply(List.<JCExpression>nil(), maker.Ident(superName), args));
		JCExpression causeNotNull = maker.Binary(CTC_NOT_EQUAL, maker.Ident(causeName), maker.Literal(CTC_BOT, null));
		JCStatement initCauseCall = maker.Exec(maker.Apply(List.<JCExpression>nil(), maker.Select(maker.Ident(superName), typeNode.toName("initCause")), List.<JCExpression>of(maker.Ident(causeName))));
		JCStatement initCause = maker.If(causeNotNull, initCauseCall, null);
		JCMethodDecl constr = createConstructor(level, typeNode, true, true, source, List.of(superCall, initCause));
		injectMethod(typeNode, constr);
	}

	private static MemberExistsResult hasConstructor(JavacNode node, Class<?>... paramTypes) {
		node = upToTypeNode(node);

		if (node != null && node.get() instanceof JCClassDecl) {
			for (JCTree def : ((JCClassDecl) node.get()).defs) {
				if (def instanceof JCMethodDecl) {
					JCMethodDecl md = (JCMethodDecl) def;
					if (md.name.contentEquals("<init>") && (md.mods.flags & Flags.GENERATEDCONSTR) == 0) {
						if (!paramsMatch(node, md.params, paramTypes)) continue;
						return getGeneratedBy(def) == null ? MemberExistsResult.EXISTS_BY_USER : MemberExistsResult.EXISTS_BY_LOMBOK;
					}
				}
			}
		}

		return MemberExistsResult.NOT_EXISTS;
	}

	private static boolean paramsMatch(JavacNode node, List<JCVariableDecl> a, Class<?>[] b) {
		if (a == null) return b == null || b.length == 0;
		if (b == null) return a.size() == 0;
		if (a.size() != b.length) return false;

		for (int i = 0; i < a.size(); i++) {
			JCVariableDecl param = a.get(i);
			Class<?> c = b[i];
			if (!typeMatches(c, node, param.vartype)) return false;
		}

		return true;
	}

	private static void addConstructorProperties(JCModifiers mods, JavacNode node, boolean msgParam, boolean causeParam) {
		if (!msgParam && !causeParam) return;
		JavacTreeMaker maker = node.getTreeMaker();
		JCExpression constructorPropertiesType = chainDots(node, "java", "beans", "ConstructorProperties");
		ListBuffer<JCExpression> fieldNames = new ListBuffer<JCExpression>();
		if (msgParam) fieldNames.append(maker.Literal("message"));
		if (causeParam) fieldNames.append(maker.Literal("cause"));
		JCExpression fieldNamesArray = maker.NewArray(null, List.<JCExpression>nil(), fieldNames.toList());
		JCAnnotation annotation = maker.Annotation(constructorPropertiesType, List.of(fieldNamesArray));
		mods.annotations = mods.annotations.append(annotation);
	}

	@SuppressWarnings("deprecation") private static JCMethodDecl createConstructor(AccessLevel level, JavacNode typeNode, boolean msgParam, boolean causeParam, JavacNode source, List<JCStatement> statements) {
		JavacTreeMaker maker = typeNode.getTreeMaker();

		boolean addConstructorProperties;
		if ((!msgParam && !causeParam) || isLocalType(typeNode) || !LombokOptionsFactory.getDelombokOptions(typeNode.getContext()).getFormatPreferences().generateConstructorProperties()) {
			addConstructorProperties = false;
		} else {
			Boolean v = typeNode.getAst().readConfiguration(ConfigurationKeys.ANY_CONSTRUCTOR_ADD_CONSTRUCTOR_PROPERTIES);
			addConstructorProperties = v != null ? v.booleanValue() :
				Boolean.FALSE.equals(typeNode.getAst().readConfiguration(ConfigurationKeys.ANY_CONSTRUCTOR_SUPPRESS_CONSTRUCTOR_PROPERTIES));
		}

		ListBuffer<JCVariableDecl> params = new ListBuffer<JCVariableDecl>();

		if (msgParam) {
			Name fieldName = typeNode.toName("message");
			long flags = JavacHandlerUtil.addFinalIfNeeded(Flags.PARAMETER, typeNode.getContext());
			JCExpression pType = genJavaLangTypeRef(typeNode, "String");
			JCVariableDecl param = maker.VarDef(maker.Modifiers(flags), fieldName, pType, null);
			params.append(param);
		}

		if (causeParam) {
			Name fieldName = typeNode.toName("cause");
			long flags = JavacHandlerUtil.addFinalIfNeeded(Flags.PARAMETER, typeNode.getContext());
			JCExpression pType = genJavaLangTypeRef(typeNode, "Throwable");
			JCVariableDecl param = maker.VarDef(maker.Modifiers(flags), fieldName, pType, null);
			params.append(param);
		}

		JCModifiers mods = maker.Modifiers(toJavacModifier(level), List.<JCAnnotation>nil());
		if (addConstructorProperties) addConstructorProperties(mods, typeNode, msgParam, causeParam);
		return recursiveSetGeneratedBy(maker.MethodDef(mods, typeNode.toName("<init>"),
			null, List.<JCTypeParameter>nil(), params.toList(), List.<JCExpression>nil(),
			maker.Block(0L, statements), null), source);
	}

	public static boolean isLocalType(JavacNode type) {
		Kind kind = type.up().getKind();
		if (kind == Kind.COMPILATION_UNIT) return false;
		if (kind == Kind.TYPE) return isLocalType(type.up());
		return true;
	}
}

